import { useEffect, useRef, useState } from 'react'
import QRCode from 'qrcode'
import { Icon } from './ui'

export function QR({ value }: { value: string }) {
  const [svg, setSvg] = useState('')
  useEffect(() => {
    let live = true
    QRCode.toString(value, { type: 'svg', margin: 0, errorCorrectionLevel: 'M', color: { dark: '#1c1a17', light: '#ffffff' } })
      .then((s) => live && setSvg(s))
      .catch(() => live && setSvg(''))
    return () => {
      live = false
    }
  }, [value])
  // The SVG is generated by the qrcode library from our own URL, never from user input.
  return <div className="qr" role="img" aria-label={`QR code for ${value}`} dangerouslySetInnerHTML={{ __html: svg }} />
}

export function CopyLink({ url }: { url: string }) {
  const [copied, setCopied] = useState(false)
  const input = useRef<HTMLInputElement>(null)

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(url)
      setCopied(true)
      setTimeout(() => setCopied(false), 1500)
    } catch {
      // Clipboard API unavailable: select the text so it can be copied by hand.
      input.current?.select()
    }
  }

  return (
    <div className="url-box">
      <input ref={input} type="text" readOnly value={url.replace(/^https?:\/\//, '')} aria-label="Poll link" onFocus={(e) => e.target.select()} />
      <button type="button" className="btn sm" onClick={copy} aria-live="polite">
        {copied ? 'Copied' : <Icon name="copy" />}
        <span className="sr-only">{copied ? '' : 'Copy link'}</span>
      </button>
    </div>
  )
}
